# Airway, Respiration and Ventilation (NREMT AEMT test plan: 9% to 13%).
# AEMT scope (National EMS Scope of Practice Model 2019, change notices 1.0 and 2.0):
# supraglottic airways, CPAP, waveform capnography, tracheobronchial suctioning of an
# intubated patient, nebulized beta agonist and anticholinergic. Intubation, needle
# decompression and cricothyrotomy are paramedic skills and appear only as wrong options.
# Clinical figures: NASEMSO National Model EMS Clinical Guidelines v3.0 (2022),
# Airway Management, Respiratory Distress and Anaphylaxis guidelines.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Supraglottic airway", "After placing a supraglottic airway, which finding best confirms that the lungs are being ventilated?",
      ["Waveform capnography", "SpO2 rising over 2 minutes", "Fog inside the airway tube", "No gurgling over the stomach"],
      "A square, repeating capnography waveform shows exhaled CO2 with each breath, which only happens when air reaches the lungs. Oxygen saturation lags behind by minutes, and tube fogging or quiet epigastric sounds can mislead."),
    S(1, 2, "Capnography", "Capnography on a patient with wheezing shows a rounded, sloping upstroke like a shark fin. This pattern suggests:",
      ["Narrowed lower airways", "A displaced airway device", "Return of a pulse", "Rebreathing of exhaled gas"],
      "A slow, sloping rise in exhaled CO2 means air leaves the lungs slowly through narrowed bronchioles, as in asthma or COPD. A flat line suggests a displaced device, and a rising baseline points to rebreathing."),
    S(1, 2, "CPAP", "How does CPAP help a patient with acute pulmonary edema?",
      ["It keeps alveoli open", "It dries the lungs out", "It slows the heart rate", "It replaces the need for oxygen"],
      "Steady positive pressure splints the alveoli open so oxygen can cross, reduces the work of breathing and lowers the return of blood to the congested lungs."),
    S(1, 2, "Ventilation rate", "A 4-year-old is breathing 6 times a minute with a strong pulse. How often should you give a BVM breath?",
      ["Every 2 to 3 seconds", "Every 6 seconds", "Every 10 seconds", "Once every 1 second"],
      "Children who need assisted ventilation with a pulse get a breath every 2 to 3 seconds, 20 to 30 a minute. Every 6 seconds is the adult rate, and faster breaths cause gastric distension."),
    O(1, 2, "Supraglottic airway insertion", "Place the steps for inserting a supraglottic airway in an apneic adult in order.",
      ["Oxygenate with a BVM and adjunct", "Size the device to the patient", "Lubricate the back of the device", "Slide it along the hard palate", "Ventilate and confirm with ETCO2", "Secure the device in place"],
      "Oxygenate first so the attempt does not cause hypoxia, then choose the size, lubricate, insert along the palate until resistance, confirm with waveform capnography and secure it so it cannot move during transport."),
    S(1, 1, "Nasopharyngeal airway", "Which finding makes a nasopharyngeal airway a poor choice?",
      ["Clear fluid from the nose", "An intact gag reflex", "Clenched teeth during a seizure", "Snoring respirations at 10/min"],
      "Clear fluid from the nose after head trauma suggests a skull base fracture, and a nasal airway could pass through it. A gag reflex, clenched teeth and snoring are reasons a nasal airway is chosen."),
    S(1, 2, "Pulse oximetry", "A family is found sleeping in a garage with a running generator. Why might pulse oximetry mislead you?",
      ["It reads CO as oxygen", "Cold fingers make it read high", "It cannot detect cyanosis", "It drops whenever HR rises"],
      "Standard pulse oximeters cannot tell carboxyhemoglobin from oxyhemoglobin, so a poisoned patient may show a normal SpO2. Cold fingers usually cause a failed or low reading, not a falsely high one."),
    S(1, 3, "Bronchodilators", "An adult with severe asthma is getting nebulized albuterol. Which medication is often added to it?",
      ["Ipratropium", "Diphenhydramine", "Ondansetron", "Aspirin"],
      "Ipratropium, an anticholinergic, works with albuterol to open the airways in a severe attack and is within AEMT scope by protocol. Diphenhydramine treats itching and hives, not bronchospasm."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Tracheostomy care", "Before suctioning a patient's tracheostomy tube, what should you do?",
      ["Preoxygenate the patient", "Deflate the cuff fully", "Insert the catheter with suction on", "Remove the inner cannula"],
      "Suctioning removes oxygen along with secretions, so preoxygenate first. Suction is applied only while withdrawing the catheter, and the cuff and inner cannula are left alone unless the tube is blocked."),
    S(2, 2, "Oxygen in COPD", "An alert COPD patient has an SpO2 of 91 percent and mild distress. What is the best oxygen approach?",
      ["Titrate to a modest target", "Nonrebreather at 15 L/min", "No oxygen at all", "BVM breaths every 6 seconds"],
      "Oxygen is a drug with a dose: patients with chronic lung disease often do well at a saturation around 90 percent, and high flows can worsen CO2 retention. Withholding it is also wrong when the patient is hypoxic."),
    M(2, 2, "Inadequate breathing", "Which findings show an adult needs assisted ventilation? Select three.",
      ["Rate of 6 with shallow breaths", "ETCO2 climbing to 62 mm Hg", "Drowsy with bluish lips", "Speaks in full sentences", "Rate of 22 with SpO2 95 percent", "Uses pursed lips at rest"],
      "A slow, shallow rate, a rising ETCO2 and falling mental status with cyanosis all show the patient is not moving enough air. Full sentences, a good saturation and pursed-lip breathing show the patient is still compensating."),
    S(2, 1, "Epiglottitis", "A drooling 6-year-old with a high fever is sitting forward and will not lie down. What should you avoid?",
      ["Looking in the throat", "Letting her sit upright", "Blow-by oxygen", "A parent riding along"],
      "These are signs of epiglottitis, and a tongue blade or a forced position can trigger complete obstruction. Keep the child calm and upright with a parent and give oxygen she will tolerate."),
    S(2, 2, "Gastric distension", "During BVM ventilation the patient's abdomen swells. What most often causes this?",
      ["Breaths too fast or too big", "A jaw thrust held too firmly", "An oral airway sized too small", "Oxygen flow set at 15 L/min"],
      "Large or rapid breaths open the esophagus and push air into the stomach, raising the risk of vomiting and aspiration. Slow breaths of just enough volume to raise the chest prevent it."),
    S(2, 3, "Capnography", "ETCO2 suddenly drops to zero in an apneic patient ventilated through a supraglottic airway. What should you suspect first?",
      ["Displaced or blocked device", "The patient is hyperventilating", "Lung compliance has improved", "Cardiac output has risen"],
      "A sudden flat line means no CO2 is coming back, most often from a dislodged, kinked or disconnected airway. Check the device and tubing at once; hyperventilation lowers ETCO2 gradually, it does not erase it."),
    S(2, 2, "Oxygen devices", "When is a Venturi mask the best oxygen device?",
      ["When a precise FiO2 is needed", "When the patient is apneic", "When the patient needs maximum oxygen", "When the patient breathes by mouth"],
      "A Venturi mask mixes air and oxygen through a fixed port to give an exact concentration, useful in chronic lung disease. Apnea needs a BVM, and a nonrebreather gives the most oxygen to a breathing patient."),
    S(2, 3, "Home ventilator", "A patient on a home ventilator through a tracheostomy is in distress and the alarm sounds. What first?",
      ["Disconnect; ventilate with a BVM", "Turn up the ventilator rate", "Silence the alarm; reassess later", "Remove the tracheostomy tube"],
      "When a ventilated patient is struggling, take the machine out of the equation: disconnect it and bag through the tracheostomy, then look for displacement, obstruction or a pneumothorax."),
    # ---------- Drill only ----------
    X(0, 2, "CPAP selection", "For each adult in respiratory distress, specify whether CPAP is appropriate.",
      ["Alert after a near-drowning, crackles", "Alert dialysis patient who missed sessions, crackles", "Breathing 6 a minute, barely rousable", "SBP 82 with cool, clammy skin", "Facial fractures from a fall"],
      ["CPAP appropriate", "CPAP not appropriate"], [0, 0, 1, 1, 1],
      "NASEMSO supports CPAP for awake drowning patients in distress and for fluid overload such as missed dialysis. A patient who cannot protect the airway or breathe adequately needs BVM ventilation, low blood pressure worsens with positive pressure, and facial fractures prevent a safe mask seal."),
    S(0, 1, "Oral airway", "An oral airway should only be inserted in a patient who:",
      ["Has no gag reflex", "Is breathing over 20 a minute", "Has a suspected neck injury", "Can follow simple commands"],
      "An oral airway in a patient with a gag reflex can cause vomiting and aspiration. A patient who follows commands protects his own airway, and a neck injury does not decide the choice."),
    S(0, 2, "Ventilation volume", "What volume should each BVM breath deliver to an adult?",
      ["Enough to see the chest rise", "The full bag squeezed hard", "Half the bag every 3 seconds", "Enough to make the belly rise"],
      "Guidelines call for about 6 to 8 mL/kg, which is the volume that makes the chest start to rise. Squeezing the whole bag raises chest pressure, lowers blood return to the heart and fills the stomach."),
    S(0, 2, "Anaphylaxis airway", "A patient stung by a wasp has stridor and hives. What treats the stridor first?",
      ["IM epinephrine", "Nebulized albuterol", "Oral diphenhydramine", "A nasal airway and BVM"],
      "Stridor in anaphylaxis is upper airway swelling, and IM epinephrine is the first treatment. Albuterol helps wheezing, not upper airway edema, and an antihistamine works too slowly."),
    S(0, 3, "Capnography", "A teen in diabetic ketoacidosis is breathing deep and fast, with an ETCO2 of 20 mm Hg. What does the low reading reflect?",
      ["Breathing off acid as CO2", "A blocked airway", "Rising CO2 retention", "A failing capnography sensor"],
      "In DKA the body compensates for acid by blowing off CO2, so ETCO2 falls well below the normal 35 to 45 mm Hg. Do not try to slow this breathing; it is the patient's own correction."),
    S(0, 2, "Suctioning", "While suctioning a vomiting patient, when should suction be applied?",
      ["As the catheter comes out", "Only while it is inserted", "For 30 seconds at a time", "Before turning the patient"],
      "Suction is applied as the tip is withdrawn and kept brief, about 15 seconds or less in an adult, with oxygen between passes. Rolling the patient onto the side first lets gravity clear most of the vomit."),
]
